function ScrollEffects() { const [location] = useLocation(); useEffect(() => { const nodes = Array.from(document.querySelectorAll("main section, section, .case-study, .media-card, .voice-card, .proof-tile, .service-card, .faq-section, .video-testimonial-card")); nodes.forEach(node => node.classList.add("scroll-reveal")); const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add("is-visible"); observer.unobserve(entry.target); } }), { threshold: 0, rootMargin: "0px 0px -6% 0px" }); nodes.forEach(node => observer.observe(node)); return () => observer.disconnect(); }, [location]); return null; }

function Seo() { const [location] = useLocation(); useEffect(() => { const pages = SEO_PAGES; const page = pages[location] || (location.startsWith("/blog/") ? { title: document.title, description: document.querySelector('meta[name="description"]')?.getAttribute("content") || "" } : pages["/"]); document.title = page.title; const setMeta = (selector: string, attribute: string, value: string) => { let node = document.querySelector(selector); if (!node) { node = document.createElement("meta"); node.setAttribute(attribute, selector.includes("property") ? selector.match(/property="([^"]+)"/)?.[1] || "" : selector.match(/name="([^"]+)"/)?.[1] || ""); document.head.appendChild(node); } node.setAttribute("content", value); }; setMeta('meta[name="description"]', "name", page.description); setMeta('meta[property="og:title"]', "property", page.title); setMeta('meta[property="og:description"]', "property", page.description); const schemaId = "robert-power-schema"; document.getElementById(schemaId)?.remove(); const schema = buildSchema(window.location.origin, location.replace(/\/+$/, "") || "/"); const script=document.createElement("script"); script.id=schemaId; script.type="application/ld+json"; script.textContent=JSON.stringify(schema); document.head.appendChild(script); return () => document.getElementById(schemaId)?.remove(); }, [location]); return null; }

export function LazyImage({ src, alt, className = "", priority = false }: { src: string; alt: string; className?: string; priority?: boolean }) { const [loaded, setLoaded] = useState(false); return <img src={src} alt={alt} className={`lazy-image ${loaded ? "is-loaded" : ""} ${className}`} loading={priority ? "eager" : "lazy"} decoding="async" onLoad={() => setLoaded(true)} />; }

