function Rotating({ photos, alt, priority }: { photos: string[]; alt: string; priority?: boolean }) {
  const [i, setI] = useState(0);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const t = setInterval(() => setI(n => (n + 1) % photos.length), 3800);
    return () => clearInterval(t);
  }, [photos.length]);
  return <div className="rotator">{photos.map((src, k) => <img key={src} src={src} alt={k === i ? alt : ""} aria-hidden={k !== i} loading={k === 0 && priority ? "eager" : "lazy"} className={k === i ? "on" : ""} />)}</div>;
}

