function Problem({ title, text }: { title: string; text: string }) { return <div className="problem"><span><Check size={15} /></span><div><h3>{title}</h3><p>{text}</p></div></div>; }

export function Installations() { return <Shell><PageIntro eyebrow="SOLAR INSTALLATIONS · HOMES + BUSINESSES" title={<>Build power that fits <em>real life.</em></>} text="Solar systems designed around your load, your budget, and the power reality of where you live and work." image={FIELD_PHOTO} imageAlt="Deye hybrid inverter and lithium battery installed by Robert Power Solutions" /><section className="section detail-section"><div className="container detail-grid"><div><div className="eyebrow">A SYSTEM, NOT A SHOPPING LIST</div><h2>Good installation starts before the first panel goes up.</h2><p className="large-copy">Robert takes time to understand what you need to power, when you need it, and how the system should behave when grid power changes.</p><a className="button button-coral" href={WA_HREF} target="_blank" rel="noreferrer"><MessageCircle size={16} /> Discuss your system</a></div><div className="install-features"><Feature title="Load assessment" text="Understand the devices, appliances, and operating pattern the system needs to support." /><Feature title="System design" text="Choose the right combination of panels, inverter, batteries, protection, and controls." /><Feature title="Professional installation" text="A clean, practical installation with attention to connections, safety, and future service." /><Feature title="Ongoing support" text="Repairs and servicing when you need help keeping the system performing." /></div></div></section><FlowSection install /><section className="field-photo"><div className="container"><LazyImage src={FIELD_PHOTO} alt="Deye hybrid inverter and lithium battery installed by Robert Power Solutions" priority /><div><span className="eyebrow">FROM THE FIELD</span><strong>Solar installations in progress across Nigeria.</strong></div></div></section><MediaProof /><ClientVoices /><ContactStrip /></Shell>; }
function Feature({ title, text }: { title: string; text: string }) { return <div className="feature"><span><Check size={15} /></span><div><h3>{title}</h3><p>{text}</p></div></div>; }

export function About() { return <Shell><PageIntro eyebrow="ABOUT ROBERT POWER SOLUTIONS" title={<>Practical expertise.<br /><em>Power you can trust.</em></>} text="A Nigeria-wide solar specialist helping homes and businesses get more from the systems they rely on." image="/images/robert-emeka-founder-with-lithium-battery-unit.webp" imageAlt="Robert Emeka, founder of Robert Power Solutions, seated beside a lithium battery power unit" /><section className="section about-detail"><div className="container about-grid"><div className="about-photo"><LazyImage src="/images/robert-portrait-white-polo.webp" alt="Robert Emeka, founder and solar engineer at Robert Power Solutions" /><span>Robert Emeka<br /><small>Founder &amp; Solar Engineer</small></span></div><div className="about-copy"><div className="eyebrow">THE PERSON BEHIND THE WORK</div><h2>“I want my clients to enjoy the outcome.”</h2><p>Robert Emeka is an Electrical / Electronics Engineer from COOU and a solar energy specialist. Through Robert Power Solutions, he installs solar systems, repairs inverters, and delivers reliable power solutions for homes and businesses. Many customers know him as <strong>Ndi Robert Emeka</strong>.</p><p>Working with customers across Nigeria by arrangement, the work is grounded in a simple idea: do the diagnosis properly, communicate clearly, and build systems people can actually depend on.</p><div className="about-facts"><span><strong>COOU</strong><small>Engineering background</small></span><span><strong>Nigeria</strong><small>Service area</small></span><span><strong>Nationwide</strong><small>Service by arrangement</small></span></div></div></div></section><ProofWall /><MediaProof /><ClientVoices /><ContactStrip /></Shell>; }

function ConsultationForm() { const [form, setForm] = useState({ name: "", phone: "", location: "", service: "Solar repair", preferred: "", details: "" }); const [errors, setErrors] = useState<Record<string, string>>({}); const [status, setStatus] = useState<"idle" | "success">("idle"); const [leadId, setLeadId] = useState(""); const [media, setMedia] = useState<File | null>(null); const [mediaPreview, setMediaPreview] = useState(""); const update = (key: string, value: string) => { setForm(current => ({ ...current, [key]: value })); setErrors(current => ({ ...current, [key]: "" })); }; const chooseMedia = (file: File | undefined) => { if (!file) return; const next: Record<string, string> = {}; if (!file.type.startsWith("image/") && !file.type.startsWith("video/")) next.media = "Choose an image or video file."; else if (file.size > 25 * 1024 * 1024) next.media = "Please keep the file under 25MB."; setErrors(current => ({ ...current, media: next.media || "" })); if (next.media) { setMedia(null); setMediaPreview(""); return; } setMedia(file); setMediaPreview(file.type.startsWith("video/") ? "video" : URL.createObjectURL(file)); }; const submit = (event: React.FormEvent) => { event.preventDefault(); const next: Record<string, string> = {}; const phoneDigits = form.phone.replace(/\D/g, ""); if (form.name.trim().length < 2) next.name = "Please enter your name."; if (phoneDigits.length < 10 || phoneDigits.length > 15) next.phone = "Enter a valid Nigerian phone number."; if (form.location.trim().length < 2) next.location = "Add your city or state."; if (form.details.trim().length > 0 && form.details.trim().length < 10) next.details = "Add a little more detail, or leave this blank."; if (Object.keys(next).length) { setErrors(next); return; } const id = `RPS-${Date.now().toString(36).toUpperCase()}`; const timestamp = new Date().toISOString(); const lead = { id, source: "website-consultation", service: form.service, region: form.location.trim(), media: media ? { name: media.name, type: media.type, size: media.size } : null, createdAt: timestamp }; try { const existing = JSON.parse(localStorage.getItem("rps_consultation_leads") || "[]"); localStorage.setItem("rps_consultation_leads", JSON.stringify([...existing.slice(-24), lead])); } catch { /* Private browsing may block local storage; WhatsApp tracking still works. */ } const win = window as Window & { dataLayer?: unknown[] }; win.dataLayer = win.dataLayer || []; win.dataLayer.push({ event: "consultation_started", ...lead }); setLeadId(id); setStatus("success"); const mediaNote = media ? ` I have selected a ${media.type.startsWith("video/") ? "video" : "photo"} named ${media.name}; I will attach it in WhatsApp after this chat opens.` : " I do not have a photo or video attached."; const message = `Hello Robert Power Solutions, I would like to book a consultation. Lead ID: ${id}. Source: website consultation form. Name: ${form.name.trim()}. Phone: ${form.phone.trim()}. Location / region: ${form.location.trim()}. Service: ${form.service}. Preferred time: ${form.preferred.trim() || "Flexible"}. Details: ${form.details.trim() || "I will explain the issue on WhatsApp."}.${mediaNote} Submitted: ${timestamp}`; window.setTimeout(() => window.open(`https://wa.me/2348028920939?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer"), 850); }; return <form className={`consultation-form ${status === "success" ? "consultation-success" : ""}`} onSubmit={submit} noValidate>{status === "success" ? <div className="consultation-success-state"><span className="success-check"><Check size={25} /></span><div className="eyebrow">REQUEST READY</div><h2>Opening WhatsApp<br /><em>for Robert.</em></h2><p>Your consultation details are tagged with <strong>{leadId}</strong>. WhatsApp will open in a moment. Please attach your selected media in the chat.</p><div className="success-progress"><span /></div><small>If WhatsApp does not open, use the chat button below.</small></div> : <><div className="eyebrow">BOOK A CONSULTATION</div><h2>Start with a clear<br /><em>next step.</em></h2><p>Share the basics, add a photo or short video if useful, and WhatsApp will open with a tagged consultation request.</p><div className="form-grid"><label>Name<input required value={form.name} onChange={event => update("name", event.target.value)} placeholder="Your name" aria-invalid={!!errors.name} />{errors.name && <small className="field-error">{errors.name}</small>}</label><label>Phone<input required value={form.phone} onChange={event => update("phone", event.target.value)} placeholder="080..." inputMode="tel" aria-invalid={!!errors.phone} />{errors.phone && <small className="field-error">{errors.phone}</small>}</label><label>City / state<input required value={form.location} onChange={event => update("location", event.target.value)} placeholder="e.g. Abuja, FCT" aria-invalid={!!errors.location} />{errors.location && <small className="field-error">{errors.location}</small>}</label><label>Service<select value={form.service} onChange={event => update("service", event.target.value)}><option>Solar repair</option><option>Inverter diagnosis</option><option>Battery service</option><option>New solar installation</option><option>System assessment</option></select></label><label>Preferred time<input value={form.preferred} onChange={event => update("preferred", event.target.value)} placeholder="e.g. Saturday morning" /></label><label className="form-full">What do you need help with?<textarea value={form.details} onChange={event => update("details", event.target.value)} placeholder="Tell Robert what the system is doing..." rows={4} aria-invalid={!!errors.details} />{errors.details && <small className="field-error">{errors.details}</small>}</label><label className="form-full media-upload-label">Photo or short video <span>Optional · max 25MB</span><input className="media-input" type="file" accept="image/*,video/*" onChange={event => chooseMedia(event.target.files?.[0])} aria-invalid={!!errors.media} />{media && <span className="media-selected">Selected: {media.name} · {(media.size / 1024 / 1024).toFixed(1)}MB</span>}{errors.media && <small className="field-error">{errors.media}</small>}{mediaPreview && mediaPreview !== "video" && <img className="media-preview" src={mediaPreview} alt="Selected solar issue preview" />}{mediaPreview === "video" && <span className="media-video-note"><Play size={14} /> Video selected — it will be ready for you to attach in WhatsApp.</span>}</label></div><button className="button button-coral" type="submit"><MessageCircle size={16} /> Continue on WhatsApp <ArrowRight size={16} /></button><small className="form-note">WhatsApp cannot receive a browser file automatically, so the message will remind you to attach the selected file.</small></>}</form>; }

function CoverageSection() { const regions = [["South West", "1–2 business days", "Oyo · Ogun · Osun · Ondo · Ekiti · Kwara"], ["South East", "2–4 business days", "Anambra · Enugu · Imo · Abia · Ebonyi"], ["South South", "3–5 business days", "Rivers · Delta · Edo · Akwa Ibom · Cross River · Bayelsa"], ["North Central", "3–5 business days", "Abuja / FCT · Benue · Kogi · Nasarawa · Niger · Plateau"], ["North West & North East", "5–7 business days", "Kano · Kaduna · Katsina · Sokoto · Borno · Yobe · and surrounding states"]]; return <section className="coverage-section"><div className="container"><div className="coverage-head"><div><div className="eyebrow">NATIONWIDE COVERAGE</div><h2>Wherever you are in Nigeria,<br /><em>start with a message.</em></h2></div><p>Response times are planning estimates for the first reply or a possible site visit. They depend on the fault, travel route, access, and technician availability.</p></div><div className="coverage-grid">{regions.map(([region, time, states]) => <div className="coverage-card" key={region}><span className="coverage-dot" /><h3>{region}</h3><strong>{time}</strong><p>{states}</p></div>)}</div><div className="coverage-note"><Clock3 size={16} /><span><strong>Urgent or remote requests:</strong> send your city, fault video, and preferred timing. Robert will confirm the earliest practical route before any visit is arranged.</span></div></div></section>; }

export function Contact() { return <Shell><PageIntro eyebrow="CONTACT ROBERT POWER SOLUTIONS" title={<>Let’s talk about<br /><em>your power.</em></>} text="Tell us what is happening with your system, where you are located, and the best way to reach you." /><section className="section contact-section"><div className="container contact-grid"><div className="contact-details"><div className="contact-item"><span><Phone size={18} /></span><div><small>CALL ROBERT</small><a href={PHONE_HREF}>{PHONE}</a></div></div><div className="contact-item"><span><MessageCircle size={18} /></span><div><small>WHATSAPP</small><a href={WA_HREF} target="_blank" rel="noreferrer">Start a conversation</a></div></div><div className="contact-item"><span><MapPin size={18} /></span><div><small>SERVICE AREA</small><strong>Across Nigeria by arrangement</strong><p>Share your city or state when you enquire so travel and site requirements are clear.</p></div></div><div className="contact-item"><span><Clock3 size={18} /></span><div><small>AVAILABILITY</small><strong>Monday – Saturday · 8am – 6pm</strong><p>Emergency and out-of-hours requests are handled subject to availability.</p></div></div><div className="contact-item"><span><Facebook size={18} /></span><div><small>FOLLOW THE WORK</small><a href={FACEBOOK_PROFILE} target="_blank" rel="noreferrer">Robert Emeka on Facebook</a><a href={X_PROFILE} target="_blank" rel="noreferrer" style={{ display: "block", marginTop: 4 }}>@RobertSolarspro on X</a></div></div></div><ConsultationForm /> <div className="contact-card"><div className="eyebrow">THE FASTEST WAY TO GET HELP</div><h2>Send the fault<br /><em>on WhatsApp.</em></h2><p>Include your location, inverter brand, what the system is doing, and a photo or short video if you can.</p><a className="button button-dark" href={WA_HREF} target="_blank" rel="noreferrer"><MessageCircle size={16} /> WhatsApp Robert <ArrowRight size={16} /></a><div className="contact-card-note"><Check size={14} /> No pressure. We start with the facts.</div></div></div></section><MediaProof /><ClientVoices /><CoverageSection /></Shell>; }

const caseStudyData = [
  { id: "inverter", category: "repair", number: "01", photo: REPAIR_PHOTO, title: "Inverter repair and fault recovery", location: "Public repair reel · Nigeria", fault: "System beeping, switching off, and refusing to carry the expected load.", process: "Start with the symptom. Test the inverter, battery bank, connections, and protection points. Isolate the fault before discussing replacement.", outcome: "A clearer diagnosis, a practical repair path, and a customer who understands what to watch next.", reverse: false },
  { id: "home-system", category: "installation", number: "02", photo: FIELD_PHOTO, title: "A complete home power system", location: "Installation evidence · Onitsha, Nigeria", fault: "A home needed stable power for everyday appliances without guessing at a shopping list.", process: "Map the load, understand the usage pattern, size the system around real life, then install with future service in mind.", outcome: "A system designed around the home's actual priorities, with a clear route to support after installation.", reverse: true },
  { id: "battery", category: "repair", number: "03", photo: REPAIR_PHOTO, title: "Battery and inverter performance checks", location: "Repair evidence · Nigeria", fault: "Backup time dropped and the batteries were no longer behaving consistently.", process: "Review charging behaviour, inspect connections, check the bank as a system, and separate a battery problem from an inverter problem.", outcome: "A more informed replacement decision and a clearer maintenance plan for dependable backup.", reverse: false },
];

export function CaseStudies() { const [filter, setFilter] = useState("all"); const visible = caseStudyData.filter(item => filter === "all" || item.category === filter); return <Shell><PageIntro eyebrow="CASE STUDIES · REPAIR + INSTALLATION" title={<>The work behind<br /><em>the outcome.</em></>} text="A closer look at the faults, decisions, and practical work that turn unreliable solar systems into dependable power." /><section className="case-intro section"><div className="container case-intro-grid"><div><div className="eyebrow">WHY THIS PAGE EXISTS</div><h2>People trust the process<br /><em>when they can see it.</em></h2></div><p>Every project starts differently. The useful story is not just the equipment list; it is the symptom, the diagnosis, the repair, and what changed for the customer afterwards.</p></div></section><section className="case-filter-section"><div className="container case-filter-inner"><div><div className="eyebrow">PROJECT LIBRARY</div><h2>Find the work<br /><em>closest to your need.</em></h2></div><div className="case-filters" role="group" aria-label="Filter case studies"><button className={filter === "all" ? "case-filter-active" : ""} onClick={() => setFilter("all")}>All projects <span>{caseStudyData.length}</span></button><button className={filter === "repair" ? "case-filter-active" : ""} onClick={() => setFilter("repair")}>Repairs <span>{caseStudyData.filter(item => item.category === "repair").length}</span></button><button className={filter === "installation" ? "case-filter-active" : ""} onClick={() => setFilter("installation")}>Installations <span>{caseStudyData.filter(item => item.category === "installation").length}</span></button></div></div></section>{visible.map(item => <CaseStudy key={item.id} {...item} />)}<VideoTestimonials /><section className="before-after-section"><div className="container"><div className="before-after-heading"><div><div className="eyebrow">SEE THE DIFFERENCE</div><h2>From uncertain<br /><em>to understood.</em></h2></div><p>Drag the handle to compare two real public Robert field visuals: an inverter-repair frame and an installation frame. They are sourced project evidence, not a claim that both frames are the same job.</p></div><BeforeAfter /></div></section><MediaProof /><ContactStrip /></Shell>; }

function CaseStudy({ number, photo, title, location, fault, process, outcome, reverse = false }: { number: string; photo: string; title: string; location: string; fault: string; process: string; outcome: string; reverse?: boolean }) { const sourceHref = title.toLowerCase().includes("inverter") || title.toLowerCase().includes("battery") ? REPAIR_VIDEO : FACEBOOK_VIDEO; return <article className={`case-study ${reverse ? "case-study-reverse" : ""}`}><div className="container case-study-grid"><div className="case-study-image"><LazyImage src={photo} alt={`${title} field visual`} /><span className="case-study-number">{number}</span><span className="case-study-caption">PUBLIC ROBERT MEDIA · SOURCE LINK BELOW</span></div><div className="case-study-copy"><div className="eyebrow">{location}</div><h2>{title}</h2><div className="case-step"><span>THE FAULT</span><p>{fault}</p></div><div className="case-step"><span>THE PROCESS</span><p>{process}</p></div><div className="case-step case-step-outcome"><span>THE OUTCOME</span><p>{outcome}</p></div><div className="case-actions"><a className="arrow-link" href={WA_HREF} target="_blank" rel="noreferrer">Discuss a similar project <ArrowRight size={15} /></a><a className="case-source-link" href={sourceHref} target="_blank" rel="noreferrer">View public source <ExternalLink size={13} /></a></div></div></div></article>; }

function VideoTestimonials() { const videos = [{ name: "Fidelis Edovia", location: "Benin City, Edo", text: "Named in Robert's public client video and in a public project story about a multi-million-naira solar installation.", href: TESTIMONIAL_VIDEO, label: "Customer named in public video" }, { name: "Okeke Pascal Chinemerem", location: "Eastern Nigeria", text: "Named in Robert's public client video and in a public recommendation shared after a solar project.", href: TESTIMONIAL_VIDEO, label: "Customer named in public video" }, { name: "Chijioke Okeke", location: "Nigeria", text: "Named alongside other clients in Robert's public video of customers enjoying designed solar systems.", href: TESTIMONIAL_VIDEO, label: "Customer named in public video" }]; return <section className="video-testimonials"><div className="container"><div className="video-testimonials-head"><div><div className="eyebrow">CUSTOMER REVIEW VIDEO · PUBLIC SOURCE</div><h2>Hear from the people<br /><em>behind the proof.</em></h2></div><p>These names are attributed to Robert's public 46-second customer video. Exact project locations are shown only where the public source supports them; Robert can replace or expand these with permissioned uploads.</p></div><div className="video-testimonial-grid">{videos.map((video, index) => <a className="video-testimonial-card" href={video.href} target="_blank" rel="noreferrer" key={video.name}><div className="video-thumb"><LazyImage src={index === 0 ? FIELD_PHOTO : (index === 1 ? REPAIR_PHOTO : ROBERT_PHOTO)} alt={`${video.name} customer review video`} /><span><Play size={15} fill="currentColor" /></span></div><div className="video-testimonial-copy"><small>{video.label} · 0{index + 1}</small><h3>{video.name}</h3><p><strong>{video.location}</strong><br />{video.text}</p><ArrowRight size={16} /></div></a>)}</div></div></section>; }

function BeforeAfter() { const [position, setPosition] = useState(52); return <div className="before-after"><div className="before-after-frame"><LazyImage src={FIELD_PHOTO} alt="Public Robert Power Solutions installation visual" /><div className="before-layer" style={{ width: `${position}%` }}><LazyImage src={REPAIR_PHOTO} alt="Public Robert Emeka inverter repair visual" /></div><span className="before-label">REPAIR · INVERTER</span><span className="after-label">INSTALL · FIELD READY</span><div className="slider-handle" style={{ left: `${position}%` }}><span>↔</span></div><input aria-label="Compare before and after images" type="range" min="8" max="92" value={position} onChange={event => setPosition(Number(event.target.value))} /></div><div className="before-after-note"><span><i className="swatch swatch-before" /> Public repair visual</span><span><i className="swatch swatch-after" /> Public installation visual</span><small>Sources: Robert Emeka public Facebook media · add a matched customer pair when permissioned</small></div></div>; }

export function Privacy() { return <LegalPage title="Privacy policy" updated="5 September 2026"><p>This policy explains how Robert Power Solutions handles information you share through this website, WhatsApp, phone, or social media.</p><h2>Information we may receive</h2><p>We may receive your name, phone number, location, equipment details, photographs, videos, and the details you provide about your solar system or service request.</p><h2>How we use information</h2><p>We use this information to respond to enquiries, assess service needs, arrange visits, provide quotes, deliver repairs or installations, and communicate about an active job. We do not sell your personal information.</p><h2>Third-party services</h2><p>When you choose to contact us through WhatsApp, Facebook, X, phone, or another platform, that platform's own privacy policy also applies.</p><h2>Your choices</h2><p>You may ask us to correct or delete personal information we hold about you, subject to any legal or operational requirement to retain it. Contact <a href={WA_HREF} target="_blank" rel="noreferrer">WhatsApp Robert</a> or call {PHONE}.</p></LegalPage>; }
export function Terms() { return <LegalPage title="Terms and conditions" updated="5 September 2026"><p>These terms govern your use of the Robert Power Solutions website and the services arranged through it.</p><h2>Information on this website</h2><p>This website provides general information about solar repairs, servicing, installations, and contact options. It is not a substitute for an on-site assessment.</p><h2>Quotes and scope</h2><p>Any estimate or recommendation is subject to confirmation after the relevant inspection or assessment. The final scope, price, equipment, timing, and warranty terms should be agreed before work begins.</p><h2>Contact</h2><p>Questions can be sent to <a href={WA_HREF} target="_blank" rel="noreferrer">WhatsApp Robert</a> or {PHONE}.</p></LegalPage>; }
function LegalPage({ title, updated, children }: { title: string; updated: string; children: ReactNode }) { return <Shell><section className="legal-hero"><div className="container"><div className="eyebrow">ROBERT POWER SOLUTIONS</div><h1>{title}</h1><p>Last updated {updated}</p></div></section><article className="legal-content container">{children}</article></Shell>; }
export function NotFoundPage() { return <Shell><PageIntro eyebrow="404" title={<>This page is <em>offline.</em></>} text="The page you are looking for does not exist, but Robert can still help with your solar system." /><div className="container not-found"><Link className="button button-coral" href="/">Back to home</Link></div></Shell>; }

function Step({ n, title, text }: { n: string; title: string; text: string }) { return <div className="step"><span>{n}</span><h3>{title}</h3><p>{text}</p></div>; }
function Chevron() { return <ChevronRight size={15} />; }
